import SwiftUI
import WebKit
import AppKit

/// How the preview pane displays a `.md` file (Formatted / Raw).
enum MarkdownDisplayMode: String, CaseIterable, Identifiable {
    case formatted = "Formatted"
    case raw = "Raw"
    var id: String { rawValue }
}

/// Neat, formatted Markdown rendering in an offline WKWebView (ADR-008).
///
/// The page is generated by `MarkdownHTML`: local images are embedded as data
/// URIs and Mermaid diagrams render via the bundled mermaid.js (JavaScript is
/// therefore enabled for this page only; navigation stays locked down — link
/// clicks open in the default browser and load failures show an error page).
/// Pass `textOverride` to preview an unsaved draft in the editor.
struct FormattedMarkdownView: NSViewRepresentable {
    let url: URL
    var textOverride: String?
    var wikilinkRoots: [URL] = []

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeNSView(context: Context) -> WKWebView {
        let configuration = WKWebViewConfiguration()
        configuration.userContentController.add(context.coordinator, name: "motstarOpen")

        let webView = WKWebView(frame: .zero, configuration: configuration)
        webView.navigationDelegate = context.coordinator
        // Let AppState scroll the preview to a heading from the outline pane.
        AppState.shared.previewWebView = webView
        load(url: url, textOverride: textOverride, into: webView, coordinator: context.coordinator)
        return webView
    }

    func updateNSView(_ webView: WKWebView, context: Context) {
        guard context.coordinator.lastLoadedPath != url.path else { return }
        load(url: url, textOverride: textOverride, into: webView, coordinator: context.coordinator)
    }

    private func load(url: URL, textOverride: String?, into webView: WKWebView, coordinator: Coordinator) {
        let html: String?
        if let textOverride {
            html = MarkdownHTML.document(markdown: textOverride, baseDirectory: url.deletingLastPathComponent(), wikilinkRoots: wikilinkRoots)
        } else if let text = MarkdownHTML.readText(url) {
            html = MarkdownHTML.document(markdown: text, baseDirectory: url.deletingLastPathComponent(), wikilinkRoots: wikilinkRoots)
        } else {
            html = nil
        }

        guard let html else {
            coordinator.showError("Cannot read this Markdown file.", in: webView)
            coordinator.lastLoadedPath = url.path
            return
        }
        coordinator.lastLoadedPath = url.path
        webView.loadHTMLString(html, baseURL: nil)
    }

    /// Navigation delegate + load-failure reporting + wikilink bridge.
    final class Coordinator: NSObject, WKNavigationDelegate, WKScriptMessageHandler {
        var lastLoadedPath: String?

        func userContentController(_ userContentController: WKUserContentController,
                                   didReceive message: WKScriptMessage) {
            guard message.name == "motstarOpen",
                  let path = message.body as? String else { return }
            let url = URL(fileURLWithPath: path)
            Task { @MainActor in
                AppState.shared.selectFile(url)
            }
        }

        func showError(_ message: String, in webView: WKWebView) {
            let escaped = message
                .replacingOccurrences(of: "&", with: "&amp;")
                .replacingOccurrences(of: "<", with: "&lt;")
                .replacingOccurrences(of: ">", with: "&gt;")
            let page = """
            <html><body style="font-family:-apple-system,sans-serif;color:#888;padding:24px;">
            <p>\(escaped)</p></body></html>
            """
            webView.loadHTMLString(page, baseURL: nil)
        }

        func webView(
            _ webView: WKWebView,
            didFailProvisionalNavigation navigation: WKNavigation!,
            withError error: Error
        ) {
            showError("Could not load the preview: \(error.localizedDescription)", in: webView)
        }

        func webView(
            _ webView: WKWebView,
            didFail navigation: WKNavigation!,
            withError error: Error
        ) {
            showError("The preview failed to finish loading: \(error.localizedDescription)", in: webView)
        }

        func webView(
            _ webView: WKWebView,
            decidePolicyFor navigationAction: WKNavigationAction,
            decisionHandler: @escaping (WKNavigationActionPolicy) -> Void
        ) {
            if navigationAction.navigationType == .linkActivated,
               let target = navigationAction.request.url {
                NSWorkspace.shared.open(target)
                decisionHandler(.cancel)
                return
            }
            decisionHandler(.allow)
        }
    }
}

/// Native source editor (NSTextView) bound to a `TextDocument`.
struct SourceEditorView: NSViewRepresentable {
    @ObservedObject var document: TextDocument
    var wrap: Bool = true

    func makeCoordinator() -> Coordinator { Coordinator(document: document) }

    func makeNSView(context: Context) -> NSScrollView {
        let scrollView = NSTextView.scrollableTextView()
        guard let textView = scrollView.documentView as? NSTextView else {
            return scrollView
        }

        textView.delegate = context.coordinator
        textView.isRichText = false
        textView.allowsUndo = true
        textView.usesFindBar = true
        textView.isIncrementalSearchingEnabled = true
        textView.font = NSFont.monospacedSystemFont(ofSize: 13, weight: .regular)
        textView.textColor = .labelColor
        textView.backgroundColor = .textBackgroundColor
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = false
        textView.isContinuousSpellCheckingEnabled = false
        textView.smartInsertDeleteEnabled = false
        textView.textContainerInset = NSSize(width: 8, height: 8)

        // Let the shared AppState reach this view for format commands.
        AppState.shared.activeEditorTextView = textView

        applyWrap(textView, wrap: wrap)
        textView.string = document.text
        return scrollView
    }

    func updateNSView(_ scrollView: NSScrollView, context: Context) {
        guard let textView = scrollView.documentView as? NSTextView else { return }
        // Avoid clobbering the caret while the user types: only sync when the
        // view text differs from the document (e.g. after load/save).
        if textView.string != document.text {
            textView.string = document.text
        }
        applyWrap(textView, wrap: wrap)
    }

    private func applyWrap(_ textView: NSTextView, wrap: Bool) {
        textView.isHorizontallyResizable = !wrap
        textView.isVerticallyResizable = true
        textView.autoresizingMask = [.width]
        textView.textContainer?.widthTracksTextView = wrap
        textView.textContainer?.containerSize = NSSize(
            width: wrap ? textView.frame.width : .greatestFiniteMagnitude,
            height: .greatestFiniteMagnitude)
        textView.needsLayout = true
    }

    final class Coordinator: NSObject, NSTextViewDelegate {
        private let document: TextDocument

        init(document: TextDocument) {
            self.document = document
        }

        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView else { return }
            document.text = textView.string
        }
    }
}
